//! Bedrock runtime ids ↔ acacia-registry's neutral states, from `data/neutral.bin`
//! (generated by crates/acacia-registry/tools/gen.mjs, which documents the layout and the mapping rules).

use std::sync::LazyLock;

static BLOB: &[u8] = include_bytes!("../../data/neutral.bin");

/// What a Bedrock state alone can't tell about its neutral state.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct NeutralFlags(pub u8);

impl NeutralFlags {
    /// Java's `waterlogged` comes from Bedrock's liquid layer; the neutral state is the dry one.
    pub const WATERLOGGED: NeutralFlags = NeutralFlags(1);
    /// The Java block comes from a block entity (bed and banner colour, flower pot contents).
    pub const BLOCK_ENTITY: NeutralFlags = NeutralFlags(2);
    /// Some Java property isn't carried by Bedrock (`powered`, leaf `distance`...); it reads as its default.
    pub const INEXACT: NeutralFlags = NeutralFlags(4);

    pub const fn contains(self, other: Self) -> bool {
        self.0 & other.0 == other.0
    }
}

pub(super) struct Tables {
    pub to_neutral: Vec<(u32, NeutralFlags)>,
    pub from_neutral: Vec<u32>,
}

pub(super) static TABLES: LazyLock<Tables> = LazyLock::new(|| {
    assert_eq!(&BLOB[..4], b"ANB1", "neutral.bin: bad magic");
    let u32_at = |at: usize| u32::from_le_bytes(BLOB[at..at + 4].try_into().unwrap());
    let n = u32_at(4) as usize;
    let to_neutral = (0..n).map(|i| (u32_at(8 + i * 5), NeutralFlags(BLOB[12 + i * 5]))).collect();
    let at = 8 + n * 5;
    let m = u32_at(at) as usize;
    let from_neutral = (0..m).map(|i| u32_at(at + 4 + i * 4)).collect();
    Tables { to_neutral, from_neutral }
});
